SELECT AVG(unemployment_1996) AS avg_unemployment_1996
FROM districts
WHERE region = 'east Bohemia';

SELECT COUNT(*) AS women_clients
FROM clients
WHERE gender = 'female';

SELECT ROUND(AVG(
    (CAST('1999-01-01' AS DATE) - birth_date) / 365.25
), 1) AS average_age
FROM Clients;

SELECT MAX(
    FLOOR(DATEDIFF('1999-01-01', birth_date) / 365.25)
) AS oldest_age
FROM clients;

SELECT COUNT(*) AS client_count
FROM clients
WHERE birth_date BETWEEN '1970-01-01' AND '1979-12-31';

SELECT DISTINCT term_months
FROM loans
ORDER BY term_months ASC;

SELECT ROUND(
         100.0 * SUM(CASE WHEN status <> 'C' THEN 1 ELSE 0 END) / COUNT(*),
         1
       ) AS pct_running_in_debt
FROM loans;

SELECT COUNT(*) AS loan_count
FROM loans
WHERE term = 60;

SELECT COUNT(*) AS gold_card_count
FROM credit_cards
WHERE card_type = 'gold';

SELECT ROUND(
    100.0 * SUM(CASE WHEN card_type = 'classic' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS classic_percentage
FROM credit_card;

SELECT MIN(issue_date) AS earliest_issue_date
FROM card
WHERE card_type = 'gold';

SELECT MAX(issue_date) AS most_recent_issue_date
FROM cards
WHERE card_type = 'junior';

SELECT COUNT(*) AS num_credit_cards
FROM credit_cards
WHERE YEAR(issue_date) = 1998;

SELECT COUNT(*) AS credit_card_count
FROM credit_cards
WHERE issued_date < '1996-01-01';

SELECT ROUND(
    100.0 * SUM(CASE WHEN card_type = 'gold' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS gold_card_percentage
FROM credit_cards
WHERE YEAR(issue_date) = 1998;

SELECT COUNT(*) AS credit_transaction_count
FROM transactions
WHERE type = 'credit';

SELECT SUM(amount) AS total_credit_amount
FROM transactions
WHERE type = 'credit';

SELECT ROUND(
    100.0 * SUM(CASE WHEN transaction_type = 'cash_deposit' THEN 1 ELSE 0 END)
    / COUNT(*),
    2
) AS cash_deposit_percentage
FROM transactions;

SELECT COUNT(*) AS transaction_count
FROM transactions
WHERE YEAR(transaction_date) = 1997;

SELECT COUNT(*) AS negative_balance_count
FROM transactions
WHERE amount < 0;

SELECT ROUND(AVG(balance), 2) AS average_resulting_balance
FROM transactions
WHERE type = 'sanction_interest';

SELECT SUM(amount) AS total_dollars
FROM transactions
WHERE transaction_type = 'old-age pension';

SELECT COUNT(*) AS insurance_standing_orders
FROM standing_orders
WHERE purpose = 'insurance';

SELECT AVG(amount) AS average_amount
FROM standing_orders
WHERE purpose = 'leasing';

SELECT MAX(amount) AS max_amount
FROM standing_orders
WHERE order_type = 'loan_repayment';

SELECT MIN(amount) AS min_amount
FROM standing_orders
WHERE payment_type = 'insurance';

SELECT 
    100.0 * COUNT(*) FILTER (WHERE type = 'loan_repayment') / COUNT(*) AS percentage
FROM standing_orders;

SELECT COUNT(*) AS standing_order_count
FROM standing_orders
WHERE amount > 10000;

SELECT COUNT(*) AS standing_order_count
FROM standing_orders
WHERE amount BETWEEN 1000 AND 5000;

SELECT COUNT(*) AS district_count
FROM districts
WHERE region = 'South Moravia';

SELECT SUM(population) AS total_inhabitants
FROM districts
WHERE region = 'Central Bohemia';

SELECT SUM(amount_usd) AS total_old_age_pension
FROM payments
WHERE payment_type = 'old_age_pension';

SELECT COUNT(DISTINCT account_id) AS account_count
FROM statements
WHERE statement_frequency = 'weekly';

SELECT AVG(approved_amount_usd) AS average_approved_amount
FROM loans
WHERE status = 'finished_no_problems';

SELECT ROUND(
    100.0 * SUM(CASE WHEN statement_frequency = 'monthly' THEN 1 ELSE 0 END) / COUNT(*),
    1
) AS pct_monthly_statements
FROM accounts;

SELECT MIN(opening_date) AS earliest_opening_date
FROM accounts
WHERE statement_frequency = 'weekly';

SELECT COUNT(*) AS account_count
FROM accounts
WHERE region = 'Prague';

SELECT COUNT(*) AS client_count
FROM clients
WHERE region = 'Prague';

SELECT ROUND(
    100.0 * SUM(CASE WHEN region = 'South Moravia' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS south_moravia_percentage
FROM clients;

SELECT COUNT(*) AS total_clients
FROM clients
WHERE region IN ('Central Bohemia', 'East Bohemia', 'North Bohemia');

SELECT ROUND(AVG(account_count), 2) AS avg_accounts_per_disponent
FROM (
    SELECT client_id, COUNT(DISTINCT account_id) AS account_count
    FROM disponent
    GROUP BY client_id
) AS per_disponent;

SELECT MAX(account_count) AS max_accounts
FROM (
    SELECT client_id, COUNT(*) AS account_count
    FROM accounts
    GROUP BY client_id
) AS counts;

SELECT ROUND(
         100.0 * SUM(CASE WHEN b.region = 'Prague' THEN 1 ELSE 0 END) / COUNT(*),
         2
       ) AS prague_percentage
FROM account a
JOIN branch b ON a.branch_id = b.branch_id;

SELECT COUNT(*) AS total_accounts
FROM accounts
WHERE region IN ('south Bohemia', 'west Bohemia');

SELECT 100.0 * SUM(CASE WHEN c.sex = 'M' THEN 1 ELSE 0 END) / COUNT(*) AS pct_male_disponents
FROM disponent d
JOIN client c ON d.client_id = c.id;
